files = {
    "app/services/product_repository.py": 'from datetime import datetime, timedelta, timezone\n\nfrom app.database.database import SessionLocal\nfrom app.database.models import ProductRecord\n\n\nclass ProductRepository:\n    """\n    Handles saving opportunity scan results to the database and\n    reading them back. Manages its own DB session per call, since\n    this is used from services (BrandScanService) rather than routes\n    that have FastAPI\'s Depends(get_db) available.\n    """\n\n    @staticmethod\n    def save_opportunity(product_dict: dict, report_dict: dict, brand_query: str):\n        db = SessionLocal()\n\n        try:\n            record = ProductRecord(\n                asin=product_dict.get("asin") or "",\n                title=product_dict.get("title") or "",\n                brand=product_dict.get("brand") or "",\n                category=product_dict.get("category") or "",\n                brand_query=brand_query,\n                buy_box_now=product_dict.get("buy_box_now") or 0.0,\n                buy_box_90d=product_dict.get("buy_box_90d") or 0.0,\n                best_source_marketplace=product_dict.get("best_source_marketplace") or "",\n                best_source_cost_gbp=product_dict.get("best_source_cost_gbp") or 0.0,\n                fba_fee=product_dict.get("fba_fee") or 0.0,\n                referral_fee=product_dict.get("referral_fee") or 0.0,\n                profit=product_dict.get("profit") or 0.0,\n                roi=product_dict.get("roi") or 0.0,\n                score=report_dict.get("score") or 0,\n                confidence=report_dict.get("confidence") or 0,\n                recommendation=report_dict.get("recommendation") or "",\n            )\n            db.add(record)\n            db.commit()\n\n        except Exception as exc:\n            db.rollback()\n            # A failed save shouldn\'t break the scan itself -- just log it.\n            print(f"Failed to save product record for {product_dict.get(\'asin\')}: {exc}")\n\n        finally:\n            db.close()\n\n    @staticmethod\n    def list_latest(limit: int = 200):\n        """\n        Returns the most recently scanned record per ASIN (not every\n        historical row) -- most recently scanned first.\n        """\n        db = SessionLocal()\n\n        try:\n            recent = (\n                db.query(ProductRecord)\n                .order_by(ProductRecord.scanned_at.desc())\n                .limit(limit * 5)  # generous overfetch before de-duplicating\n                .all()\n            )\n\n            seen = set()\n            latest = []\n\n            for record in recent:\n                if record.asin in seen:\n                    continue\n\n                seen.add(record.asin)\n                latest.append(record)\n\n                if len(latest) >= limit:\n                    break\n\n            return latest\n\n        finally:\n            db.close()\n\n    @staticmethod\n    def get_recently_scanned_asins(brand_query: str, since_hours: int) -> set:\n        """\n        Returns the set of ASINs already scanned for this brand within\n        the last `since_hours` hours -- used to skip re-spending\n        tokens on products we already have fresh data for, and lets\n        repeated scans naturally reach deeper into the catalog instead\n        of hitting the same top-ranked ASINs every time.\n        """\n        db = SessionLocal()\n\n        try:\n            cutoff = datetime.now(timezone.utc) - timedelta(hours=since_hours)\n\n            rows = (\n                db.query(ProductRecord.asin)\n                .filter(ProductRecord.brand_query == brand_query)\n                .filter(ProductRecord.scanned_at >= cutoff)\n                .all()\n            )\n\n            return {row[0] for row in rows}\n\n        finally:\n            db.close()\n',
    "app/services/brand_scan_service.py": 'from dataclasses import asdict\n\nfrom app.services.product_finder import ProductFinder\nfrom app.services.product_service import ProductService\nfrom app.services.product_mapper import ProductMapper\nfrom app.services.fee_engine import FeeEngine\nfrom app.services.opportunity_engine import OpportunityEngine\nfrom app.services.product_repository import ProductRepository\nfrom app.config.exclusions import is_excluded\n\nEU_MARKETPLACES = ["DE", "FR", "ES", "IT"]\n\n# Safety margin -- don\'t spend right down to 0, leave headroom for\n# whatever else might use the account (e.g. another tab open).\nMIN_TOKEN_BUFFER = 5\n\n# How many ASINs to request per Keepa call. Keepa allows a single\n# request to push your token balance NEGATIVE if it doesn\'t have\n# enough for the whole batch, rather than refusing it upfront -- so\n# a large batch can overshoot badly. Chunking bounds the overshoot to\n# roughly one chunk\'s worth of tokens instead of the whole scan.\nCHUNK_SIZE = 10\n\n# How long a scanned ASIN is considered "fresh enough" to skip\n# re-scanning by default. This is what stops repeated scans of the\n# same brand from re-spending tokens on the exact same top-ranked\n# products every time -- once they\'re on cooldown, the next scan\n# naturally falls through to the next tier down instead.\nRESCAN_COOLDOWN_HOURS = 24\n\n\nclass BrandScanService:\n\n    def __init__(self):\n        self.finder = ProductFinder()\n        self.product_service = ProductService()\n\n    def _fetch_in_chunks(self, asins, marketplace, cost_estimate):\n        """\n        Fetches `asins` from `marketplace` in CHUNK_SIZE pieces,\n        checking measured token budget before each chunk. Returns\n        (products, fetched_asins, ran_out: bool, updated_cost_estimate).\n\n        cost_estimate: current best guess at per-ASIN token cost for\n        this call shape, or None if not yet known. Updated after each\n        chunk from real measured spend, so later chunks (and later\n        marketplaces) use an increasingly accurate figure.\n        """\n        products = []\n        fetched_asins = []\n        ran_out = False\n\n        for i in range(0, len(asins), CHUNK_SIZE):\n            chunk = asins[i:i + CHUNK_SIZE]\n\n            tokens_now = self.product_service.api.tokens_left\n\n            if tokens_now is not None:\n                if cost_estimate is not None:\n                    estimated_cost = cost_estimate * len(chunk)\n                    if tokens_now < estimated_cost + MIN_TOKEN_BUFFER:\n                        ran_out = True\n                        break\n                elif tokens_now <= MIN_TOKEN_BUFFER:\n                    # No cost estimate yet, but already critically low --\n                    # don\'t risk even the first (measuring) chunk.\n                    ran_out = True\n                    break\n\n            tokens_before = self.product_service.api.tokens_left\n            chunk_products = self.product_service.get_products(chunk, marketplace)\n            tokens_after = self.product_service.api.tokens_left\n\n            products.extend(chunk_products)\n            fetched_asins.extend(chunk)\n\n            if tokens_before is not None and tokens_after is not None and chunk:\n                measured = max(tokens_before - tokens_after, 0) / len(chunk)\n                cost_estimate = measured\n\n        return products, fetched_asins, ran_out, cost_estimate\n\n    def scan(self, brand: str, limit: int = 20, force_rescan: bool = False):\n        """\n        Full A2A pipeline for a brand, with chunked token-budget\n        awareness so a scan never silently hangs OR blows through its\n        token budget in one oversized request. Measures real per-ASIN\n        cost as it goes and checks it before every chunk, not just\n        before every marketplace.\n\n        By default, ASINs already scanned for this brand within\n        RESCAN_COOLDOWN_HOURS are skipped BEFORE any tokens are spent\n        -- this is what stops repeated scans from re-paying for the\n        same top-ranked products, and lets later scans naturally\n        reach further into the catalog instead. Pass force_rescan=True\n        to check everything regardless of when it was last scanned.\n        """\n\n        # Step 1 - Find ASINs\n        asins = self.finder.find_brand(brand)\n\n        skipped_recently_scanned = 0\n\n        if not force_rescan:\n            recently_scanned = ProductRepository.get_recently_scanned_asins(\n                brand, RESCAN_COOLDOWN_HOURS\n            )\n            before_count = len(asins)\n            asins = [a for a in asins if a not in recently_scanned]\n            skipped_recently_scanned = before_count - len(asins)\n\n        asins = asins[:limit]\n\n        empty_response = {\n            "brand": brand, "count": 0, "opportunities": [],\n            "skipped_excluded": 0,\n            "skipped_recently_scanned": skipped_recently_scanned,\n            "marketplaces_skipped_low_tokens": [],\n            "marketplaces_partial_low_tokens": {},\n            "tokens_remaining": None,\n        }\n\n        if not asins:\n            return empty_response\n\n        tokens_before_uk = self.product_service.api.tokens_left\n\n        if tokens_before_uk is not None and tokens_before_uk <= MIN_TOKEN_BUFFER:\n            return {\n                **empty_response,\n                "tokens_remaining": tokens_before_uk,\n                "error": (\n                    f"Only {tokens_before_uk} Keepa tokens left -- not enough "\n                    f"to safely start a scan. Wait for your account to refill."\n                ),\n            }\n\n        # Step 2 - Load UK data first, in chunks (this is the only\n        # lookup we pay for regardless of exclusions -- we need it to\n        # know category). No cost estimate yet on the first call.\n        uk_products, fetched_uk_asins, uk_ran_out, cost_estimate = self._fetch_in_chunks(\n            asins, "UK", cost_estimate=None\n        )\n\n        # Step 3 - Filter out excluded categories/ASINs/gated brands\n        # BEFORE spending tokens on the 4 EU marketplaces.\n        included_uk_products = []\n        skipped_excluded = 0\n\n        for uk_product in uk_products:\n            asin = uk_product.get("asin") or ""\n            brand_name = uk_product.get("brand") or ""\n            category = str(uk_product.get("rootCategory") or "")\n\n            if is_excluded(asin, brand_name, category):\n                skipped_excluded += 1\n                continue\n\n            included_uk_products.append(uk_product)\n\n        included_asins = [p.get("asin") for p in included_uk_products]\n\n        # Step 4 - Pull EU data one marketplace at a time, in chunks,\n        # carrying the measured cost estimate forward each time.\n        eu_lookups = {}\n        marketplaces_skipped_low_tokens = []\n        marketplaces_partial_low_tokens = {}\n\n        for marketplace in EU_MARKETPLACES:\n            if not included_asins:\n                eu_lookups[marketplace] = {}\n                continue\n\n            products, fetched, ran_out, cost_estimate = self._fetch_in_chunks(\n                included_asins, marketplace, cost_estimate\n            )\n\n            eu_lookups[marketplace] = {p.get("asin"): p for p in products}\n\n            if ran_out:\n                if fetched:\n                    marketplaces_partial_low_tokens[marketplace] = {\n                        "fetched": len(fetched), "total": len(included_asins),\n                    }\n                else:\n                    marketplaces_skipped_low_tokens.append(marketplace)\n\n        opportunities = []\n\n        # Step 5 - Map, price, and score each remaining ASIN\n        for uk_product in included_uk_products:\n            asin = uk_product.get("asin")\n\n            eu_products = {\n                marketplace: lookup.get(asin)\n                for marketplace, lookup in eu_lookups.items()\n            }\n\n            product = ProductMapper.from_keepa_multi(uk_product, eu_products)\n\n            if not product.buy_box_now:\n                continue\n\n            if not product.best_source_marketplace:\n                continue\n\n            fees = FeeEngine.calculate(product)\n            product.fba_fee = fees.fba_fee\n            product.referral_fee = fees.referral_fee\n            product.profit = fees.profit\n            product.roi = fees.roi\n\n            report = OpportunityEngine.analyse(product)\n\n            product_dict = asdict(product)\n            report_dict = asdict(report)\n\n            ProductRepository.save_opportunity(product_dict, report_dict, brand)\n\n            opportunities.append({\n                "product": product_dict,\n                "report": report_dict,\n            })\n\n        # Step 6 - Rank best opportunities first\n        opportunities.sort(key=lambda o: o["report"]["score"], reverse=True)\n\n        return {\n            "brand": brand,\n            "count": len(opportunities),\n            "skipped_excluded": skipped_excluded,\n            "skipped_recently_scanned": skipped_recently_scanned,\n            "marketplaces_skipped_low_tokens": marketplaces_skipped_low_tokens,\n            "marketplaces_partial_low_tokens": marketplaces_partial_low_tokens,\n            "tokens_remaining": self.product_service.api.tokens_left,\n            "opportunities": opportunities,\n        }\n',
    "app/main.py": 'from fastapi import FastAPI\nfrom fastapi.encoders import jsonable_encoder\n\nfrom app.services.brand_scan_service import BrandScanService\nfrom app.services.product_finder import ProductFinder\nfrom app.services.product_service import ProductService\nfrom app.services.category_survey_service import CategorySurveyService\n\nfrom app.database.base import Base\nfrom app.database.database import engine\nfrom app.database import models  # noqa: F401 -- registers ProductRecord with Base.metadata\n\nfrom app.routes import dashboard, keepa, scan, analyse, opportunities_view, products\n\napp = FastAPI(title="Atlas")\n\n# Creates any tables that don\'t exist yet (e.g. product_records) without\n# touching existing ones. The old \'products\' table (incompatible legacy\n# schema) is left alone -- product_records is a separate table.\nBase.metadata.create_all(bind=engine)\n\n# NOTE: routes/add_product.py is still NOT registered -- it targets the\n# old incompatible \'products\' table. Manual add-a-product isn\'t wired\n# up yet; only scan-based persistence via product_records is.\napp.include_router(dashboard.router)\napp.include_router(keepa.router)\napp.include_router(scan.router)\napp.include_router(analyse.router)\napp.include_router(opportunities_view.router)\napp.include_router(products.router)\n\n\n@app.get("/opportunities/{brand}")\ndef opportunities_for_brand(brand: str, limit: int = 20, force_rescan: bool = False):\n    """\n    Full A2A pipeline: find a brand\'s ASINs, price them across UK/DE/FR/ES/IT,\n    apply fees, score with OpportunityEngine, and return ranked opportunities.\n    By default, ASINs scanned recently for this brand are skipped to\n    save tokens -- pass force_rescan=true to check everything anyway.\n    """\n    scanner = BrandScanService()\n    return scanner.scan(brand, limit=limit, force_rescan=force_rescan)\n\n\n@app.get("/categories/{brand}")\ndef categories_for_brand(brand: str, limit: int = 100):\n    """\n    Cheap survey of what categories a brand\'s catalog spans, using\n    only UK lookups (1x token cost per ASIN, not 5x). Use this to\n    decide what to add to app/config/exclusions.py BEFORE running\n    full /opportunities scans.\n    """\n    survey = CategorySurveyService()\n    return survey.survey(brand, limit=limit)\n\n\n@app.get("/debug/{brand}")\ndef debug_brand(brand: str):\n    """\n    Returns the raw Keepa product in a JSON-safe format.\n    """\n\n    finder = ProductFinder()\n    service = ProductService()\n\n    asins = finder.find_brand(brand)\n\n    if not asins:\n        return {"error": "No products found"}\n\n    products = service.get_products([asins[0]], "UK")\n\n    if not products:\n        return {"error": "No Keepa product returned"}\n\n    return jsonable_encoder(products[0])\n',
    "app/routes/opportunities_view.py": 'from fastapi import APIRouter, Request\nfrom fastapi.templating import Jinja2Templates\n\nfrom app.services.brand_scan_service import BrandScanService\n\nrouter = APIRouter()\n\ntemplates = Jinja2Templates(directory="app/templates")\n\n\n@router.get("/discovery")\ndef discovery(request: Request, brand: str = "", limit: int = 20,\n              profitable_only: bool = True, force_rescan: bool = False):\n    result = None\n    hidden_count = 0\n\n    if brand:\n        scanner = BrandScanService()\n        result = scanner.scan(brand, limit=limit, force_rescan=force_rescan)\n\n        # Everything is still computed and saved to the database\n        # regardless -- this only affects what\'s shown on this page,\n        # since an unprofitable item today might be worth another\n        # look later if prices/fees change.\n        if result and not result.get("error") and profitable_only:\n            all_opportunities = result["opportunities"]\n            filtered = [o for o in all_opportunities if o["product"]["profit"] > 0]\n            hidden_count = len(all_opportunities) - len(filtered)\n            result = {**result, "opportunities": filtered, "count": len(filtered)}\n\n    return templates.TemplateResponse(\n        request=request,\n        name="discovery.html",\n        context={\n            "request": request,\n            "brand": brand,\n            "limit": limit,\n            "profitable_only": profitable_only,\n            "force_rescan": force_rescan,\n            "hidden_count": hidden_count,\n            "result": result,\n        }\n    )\n',
    "app/templates/discovery.html": '{% extends "base.html" %}\n\n{% block title %}Discovery - Atlas{% endblock %}\n\n{% block content %}\n\n<div class="card metric p-4 mb-4">\n    <form method="get" action="/discovery" class="row g-3 align-items-end">\n        <div class="col-md-4">\n            <label class="form-label">Brand</label>\n            <input type="text" class="form-control" name="brand" value="{{ brand }}" placeholder="e.g. philips" required>\n        </div>\n        <div class="col-md-2">\n            <label class="form-label">Max ASINs to scan</label>\n            <input type="number" class="form-control" name="limit" value="{{ limit }}" min="1" max="500">\n        </div>\n        <div class="col-md-3">\n            <label class="form-label">Results</label>\n            <select class="form-select" name="profitable_only">\n                <option value="true" {{ "selected" if profitable_only }}>Only profitable</option>\n                <option value="false" {{ "selected" if not profitable_only }}>Show all</option>\n            </select>\n        </div>\n        <div class="col-md-3">\n            <button type="submit" class="btn btn-dark w-100">\n                <i class="bi bi-search"></i> Scan for opportunities\n            </button>\n        </div>\n    </form>\n</div>\n\n{% if result %}\n\n    {% if result.error %}\n        <div class="alert alert-warning">\n            <i class="bi bi-exclamation-triangle"></i> {{ result.error }}\n        </div>\n    {% else %}\n\n        <div class="row mb-4">\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Opportunities found</div>\n                    <h2>{{ result.count }}</h2>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Excluded (category/brand/ASIN)</div>\n                    <h2>{{ result.skipped_excluded }}</h2>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Keepa tokens remaining</div>\n                    <h2>{{ result.tokens_remaining if result.tokens_remaining is not none else "?" }}</h2>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Marketplaces skipped (low tokens)</div>\n                    <h2>{{ result.marketplaces_skipped_low_tokens | length }}</h2>\n                </div>\n            </div>\n        </div>\n\n        {% if result.skipped_recently_scanned %}\n            <div class="alert alert-secondary">\n                <i class="bi bi-clock-history"></i>\n                Skipped {{ result.skipped_recently_scanned }} product{{ "s" if result.skipped_recently_scanned != 1 }} already scanned in the last 24h (saves tokens). <a href="/discovery?brand={{ brand }}&limit={{ limit }}&profitable_only={{ profitable_only|lower }}&force_rescan=true">Force rescan everything</a>\n            </div>\n        {% endif %}\n\n        {% if hidden_count %}\n            <div class="alert alert-secondary">\n                <i class="bi bi-eye-slash"></i>\n                {{ hidden_count }} unprofitable result{{ "s" if hidden_count != 1 }} hidden. <a href="/discovery?brand={{ brand }}&limit={{ limit }}&profitable_only=false">Show all</a>\n            </div>\n        {% endif %}\n\n        {% if result.marketplaces_skipped_low_tokens %}\n            <div class="alert alert-info">\n                <i class="bi bi-info-circle"></i>\n                Skipped {{ result.marketplaces_skipped_low_tokens | join(", ") }} for some/all ASINs due to low token budget.\n            </div>\n        {% endif %}\n\n        {% if result.opportunities %}\n        <div class="card metric p-3">\n            <div class="table-responsive">\n                <table class="table table-hover align-middle">\n                    <thead>\n                        <tr>\n                            <th>Product</th>\n                            <th>Best Source</th>\n                            <th>Source Cost</th>\n                            <th>UK Price</th>\n                            <th>Profit</th>\n                            <th>ROI</th>\n                            <th>Score</th>\n                            <th>Confidence</th>\n                            <th>Recommendation</th>\n                            <th></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        {% for o in result.opportunities %}\n                        {% set p = o.product %}\n                        {% set r = o.report %}\n                        <tr>\n                            <td style="max-width:320px;">\n                                <div class="fw-semibold small">{{ p.title[:80] }}{% if p.title|length > 80 %}...{% endif %}</div>\n                                <div class="text-muted small">{{ p.asin }} &middot; {{ p.brand }}</div>\n                            </td>\n                            <td>{{ p.best_source_marketplace }}</td>\n                            <td>&pound;{{ "%.2f"|format(p.best_source_cost_gbp) }}</td>\n                            <td>&pound;{{ "%.2f"|format(p.buy_box_now) }}</td>\n                            <td class="{{ \'text-success\' if p.profit > 0 else \'text-danger\' }}">\n                                &pound;{{ "%.2f"|format(p.profit) }}\n                            </td>\n                            <td class="{{ \'text-success\' if p.roi > 0 else \'text-danger\' }}">\n                                {{ "%.1f"|format(p.roi) }}%\n                            </td>\n                            <td>{{ r.score }}</td>\n                            <td>{{ r.confidence }}%</td>\n                            <td>\n                                {% if r.recommendation == "BUY" %}\n                                    <span class="badge bg-success">BUY</span>\n                                {% elif r.recommendation == "REVIEW" %}\n                                    <span class="badge bg-warning text-dark">REVIEW</span>\n                                {% else %}\n                                    <span class="badge bg-secondary">IGNORE</span>\n                                {% endif %}\n                            </td>\n                            <td>\n                                <button class="btn btn-sm btn-outline-secondary" type="button" data-bs-toggle="collapse" data-bs-target="#why-{{ loop.index }}">\n                                    <i class="bi bi-info-circle"></i> Why?\n                                </button>\n                            </td>\n                        </tr>\n                        <tr class="collapse" id="why-{{ loop.index }}">\n                            <td colspan="10" class="bg-light">\n                                <div class="row py-2">\n                                    <div class="col-md-6">\n                                        <div class="small text-muted mb-2">\n                                            Trend: price {{ "%+.1f"|format(r.trend.price_change) }}% vs 90d avg,\n                                            offers {{ "%+.1f"|format(r.trend.offer_change) }}%,\n                                            sales rank {{ "%+.1f"|format(r.trend.rank_change) }}%\n                                        </div>\n                                        <h6 class="small fw-bold">Score factors ({{ r.score }}/100)</h6>\n                                        <ul class="list-unstyled small mb-0">\n                                        {% for f in r.score_breakdown %}\n                                            <li class="{{ \'text-success\' if f.passed else \'text-muted\' }}">\n                                                <i class="bi {{ \'bi-check-circle-fill\' if f.passed else \'bi-circle\' }}"></i>\n                                                {{ f.label }}\n                                                {% if f.passed %}<strong>({{ "+" if f.points > 0 else "" }}{{ f.points }})</strong>{% endif %}\n                                            </li>\n                                        {% endfor %}\n                                        </ul>\n                                    </div>\n                                    <div class="col-md-6">\n                                        <h6 class="small fw-bold">Confidence factors ({{ r.confidence }}/100)</h6>\n                                        <ul class="list-unstyled small mb-0">\n                                        {% for f in r.confidence_breakdown %}\n                                            <li class="{{ \'text-danger\' if f.triggered else \'text-success\' }}">\n                                                <i class="bi {{ \'bi-exclamation-triangle-fill\' if f.triggered else \'bi-check-circle-fill\' }}"></i>\n                                                {{ f.label }}\n                                                {% if f.triggered %}<strong>({{ f.points }})</strong>{% endif %}\n                                            </li>\n                                        {% endfor %}\n                                        </ul>\n                                    </div>\n                                </div>\n                            </td>\n                        </tr>\n                        {% endfor %}\n                    </tbody>\n                </table>\n            </div>\n        </div>\n        {% else %}\n            <div class="alert alert-secondary">No viable opportunities found in this batch.</div>\n        {% endif %}\n\n    {% endif %}\n\n{% endif %}\n\n{% endblock %}\n',
}

for path, content in files.items():
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"Written: {path}")

print("\nDone -- rescan cooldown feature is now in place.")